        return new Sink(createParts ? Rnd060v.CreateDatasetWriter(route, filePath, files, options)
            : Rnd060v.CreateDatasetWriter(route, files, options));
    }

    sealed class Sink(Rnd060v.DatasetWriter writer) : IRandomDatasetSink
    {
        public void Queue(object row) => writer.Queue((Rnd060v)row);
        public void Dispose() => writer.Dispose();
    }
}